/**
 * Returns the scientific name for a given FAO Alpha-3 code, or null if not found.
 * @param {string} faoCode
 * @returns {string|null}
 */
export function getScientificNameByFao(faoCode) {
  if (!faoCode) return null;
  return ASFIS_MAP[faoCode.toUpperCase()] ?? null;
}
